/* Project page logic. All content comes from data.js (generated by make_project_page.py). */
(function () {
  "use strict";
  const D = window.PAGE_DATA;
  const $ = (id) => document.getElementById(id);
  if (!D) {
    document.querySelector("main").insertAdjacentHTML("afterbegin",
      '<p style="color:#b00;padding:20px">data.js is missing. Run <code>python make_project_page.py</code> first.</p>');
    return;
  }

  const METHOD_LABEL = Object.fromEntries(D.methods.map((m) => [m.key, m.label]));
  METHOD_LABEL["Sphere Mesh"] = "Sphere mesh (ours)";
  const LOWER_BETTER = { flip: true, lpips: true, psnr: false, ssim: false };
  const METRIC_LABEL = { flip: "FLIP ↓", lpips: "LPIPS ↓", psnr: "PSNR ↑", ssim: "SSIM ↑" };

  const fmt = (v, d = 3) => (v == null || isNaN(v) ? "–" : Number(v).toFixed(d));

  function segmented(el, items, active, onChange) {
    el.innerHTML = "";
    items.forEach(([value, label]) => {
      const b = document.createElement("button");
      b.textContent = label;
      b.dataset.value = value;
      if (String(value) === String(active)) b.classList.add("active");
      b.addEventListener("click", () => {
        el.querySelectorAll("button").forEach((x) => x.classList.toggle("active", x === b));
        onChange(value);
      });
      el.appendChild(b);
    });
  }

  function bindSeg(el, attr, onChange) {
    el.querySelectorAll("button").forEach((b) =>
      b.addEventListener("click", () => {
        el.querySelectorAll("button").forEach((x) => x.classList.toggle("active", x === b));
        onChange(b.dataset[attr]);
      }));
  }

  // ------------------------------------------------------------------ figures
  Object.entries(D.figures).forEach(([name, f]) => {
    const img = $("fig-" + name);
    if (img) { img.src = f.src; img.width = f.w; img.height = f.h; img.loading = "lazy"; }
  });

  // ------------------------------------------------------------------ hero buttons
  const ICON = {
    pdf: '<svg viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zm-1 7V3.5L18.5 9z"/></svg>',
    video: '<svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>',
    code: '<svg viewBox="0 0 24 24"><path d="M9.4 16.6 4.8 12l4.6-4.6L8 6l-6 6 6 6zm5.2 0 4.6-4.6-4.6-4.6L16 6l6 6-6 6z"/></svg>',
    grid: '<svg viewBox="0 0 24 24"><path d="M3 3h8v8H3zm10 0h8v8h-8zM3 13h8v8H3zm10 0h8v8h-8z"/></svg>',
  };
  const buttons = [
    D.pdfs.paper ? ["Paper", D.pdfs.paper, "pdf"] : ["Paper", null, "pdf"],
    D.pdfs.supplement ? ["Supplement", D.pdfs.supplement, "pdf"] : null,
    ["Video", "#video", "video"],
    ["Explorer", "#explorer", "grid"],
    ["Code (upon acceptance)", null, "code"],
  ].filter(Boolean);
  $("hero-buttons").innerHTML = buttons.map(([label, href, icon]) =>
    href ? `<a class="btn" href="${href}"${href.endsWith(".pdf") ? ' target="_blank"' : ""}>${ICON[icon]}${label}</a>`
         : `<span class="btn disabled" title="Not available during review">${ICON[icon]}${label}</span>`).join("");

  // ------------------------------------------------------------------ main video
  if (D.video) {
    $("main-video").innerHTML =
      `<video controls preload="metadata" poster="${D.video.poster}" src="${D.video.src}"></video>`;
  } else {
    $("main-video").innerHTML = '<div class="placeholder">Video not built.</div>';
  }

  // ------------------------------------------------------------------ key stats
  (function keyStats() {
    const N = D.numbers || {};
    const stats = [];
    const bb = N.best_baseline;
    if (bb && bb.flip && bb.flip.all) {
      const r = bb.flip.all;
      stats.push([`${Math.round((1 - r.ours / r.other) * 100)}%`,
        `lower FLIP error than the best baseline (${METHOD_LABEL[r.baseline] || r.baseline}), averaged over all budgets`]);
      stats.push([`${Math.round(r.win_rate)}%`, `of models where ours beats the best baseline in FLIP`]);
    }
    const gs = N.geometry_stages;
    if (gs && gs.chamfer) {
      stats.push([`${Math.round(gs.chamfer.improvement)}%`,
        `lower Chamfer distance after geometry optimization than Structural-MAT`]);
    }
    if (N.speed && N.speed.length) {
      const s = N.speed[0];
      stats.push([`${s.speedup.toFixed(1)}×`,
        `faster than ${s.baseline} at ${s.spheres} spheres / ${s.baseline_prims} triangles (billboard rendering)`]);
    }
    $("key-stats").innerHTML = stats.map(([v, l]) => `<div class="stat"><div class="v">${v}</div><div class="l">${l}</div></div>`).join("");
  })();

  // ------------------------------------------------------------------ slider widget
  function makeSlider(root) {
    const clip = root.querySelector(".slider-clip");
    const handle = root.querySelector(".slider-handle");
    let pos = 0.5, dragging = false;
    const set = (p) => {
      pos = Math.min(1, Math.max(0, p));
      clip.style.clipPath = `inset(0 ${(1 - pos) * 100}% 0 0)`;
      handle.style.left = `${pos * 100}%`;
    };
    const fromEvent = (e) => {
      const r = root.getBoundingClientRect();
      set((e.clientX - r.left) / r.width);
    };
    root.addEventListener("pointerdown", (e) => { dragging = true; root.setPointerCapture(e.pointerId); fromEvent(e); });
    root.addEventListener("pointermove", (e) => { if (dragging) fromEvent(e); });
    root.addEventListener("pointerup", () => { dragging = false; });
    set(0.5);
  }
  makeSlider($("cmp-slider"));
  makeSlider($("tex-slider"));

  // ------------------------------------------------------------------ explorer
  const models = D.models;
  const state = {
    model: (models.find((m) => m.key === "horse") || models[0] || {}).key,
    budget: "20",
    baseline: "RoLoPM",
    view: "tex",
    stageKind: "tessellated",
  };
  const modelOf = (k) => models.find((m) => m.key === k);

  // model picker
  $("model-picker").innerHTML = models.map((m) =>
    `<button data-k="${m.key}" title="${m.label}"><img src="assets/thumbs/${m.key}.webp" alt="" loading="lazy"><span>${m.label}</span></button>`).join("");
  $("model-picker").querySelectorAll("button").forEach((b) =>
    b.addEventListener("click", () => { state.model = b.dataset.k; renderExplorer(true); }));

  // baseline select
  $("baseline-select").innerHTML = D.methods.map((m) => `<option value="${m.key}">${m.label}</option>`).join("");
  $("baseline-select").value = state.baseline;
  $("baseline-select").addEventListener("change", (e) => { state.baseline = e.target.value; renderExplorer(false); });

  bindSeg($("view-seg"), "v", (v) => { state.view = v; renderCompare(); });
  bindSeg($("stage-seg"), "k", (k) => { state.stageKind = k; renderStages(); });

  // turntables (kept in sync with the ground-truth clip)
  const vids = [$("tt-gt"), $("tt-ours"), $("tt-base")];
  let playing = true;
  $("tt-play").addEventListener("click", () => {
    playing = !playing;
    $("tt-play").textContent = playing ? "Pause" : "Play";
    vids.forEach((v) => (playing ? v.play().catch(() => {}) : v.pause()));
  });
  setInterval(() => {
    const master = vids[0];
    if (!playing || master.paused) return;
    vids.slice(1).forEach((v) => {
      if (v.readyState >= 2 && Math.abs(v.currentTime - master.currentTime) > 0.08) v.currentTime = master.currentTime;
    });
  }, 400);

  function setVideo(v, src) {
    if (v.getAttribute("src") === src) return false;
    v.setAttribute("src", src);
    return true;
  }

  function restartVideos() {
    let pending = vids.length;
    vids.forEach((v) => {
      const go = () => {
        if (--pending === 0) vids.forEach((x) => { x.currentTime = 0; if (playing) x.play().catch(() => {}); });
      };
      if (v.readyState >= 2) go(); else v.addEventListener("loadeddata", go, { once: true });
    });
  }

  function renderTurntables() {
    const m = modelOf(state.model);
    $("turntables").hidden = !m.video;
    $("tt-missing").hidden = !!m.video;
    document.querySelector(".tt-controls").hidden = !m.video;
    if (!m.video) return;
    const base = `assets/turntables/${m.key}`;
    const changed = [
      setVideo(vids[0], `${base}/gt.mp4`),
      setVideo(vids[1], `${base}/${state.budget}/ours.mp4`),
      setVideo(vids[2], `${base}/${state.budget}/${state.baseline}.mp4`),
    ].some(Boolean);
    if (changed) restartVideos();
  }

  function renderCompare() {
    const m = modelOf(state.model);
    const b = m.budgets[state.budget];
    const dir = `assets/explorer/${m.key}/${state.budget}`;
    const suffix = state.view === "flip" ? "_flip" : "";
    $("cmp-left").src = `${dir}/ours${suffix}.webp`;
    $("cmp-right").src = `${dir}/${state.baseline}${suffix}.webp`;
    $("cmp-gt").src = `assets/explorer/${m.key}/gt.webp`;
    const fl = b.flip || {};
    $("cmp-left-tag").textContent = `Ours · ${state.budget} spheres` + (state.view === "flip" ? ` · ${fmt(fl.ours, 4)}` : "");
    $("cmp-right-tag").textContent = `${METHOD_LABEL[state.baseline]} · ${b.prims} tris` + (state.view === "flip" ? ` · ${fmt(fl[state.baseline], 4)}` : "");
    $("flip-legend").hidden = state.view !== "flip";
    $("cmp-label").textContent = `Sphere mesh (ours) vs. ${METHOD_LABEL[state.baseline]}` + (state.view === "flip" ? " · FLIP error" : "");

    // FLIP ranking for this view
    const entries = [["ours", fl.ours]].concat(D.methods.map((x) => [x.key, fl[x.key]])).filter((e) => e[1] != null);
    entries.sort((a, b2) => a[1] - b2[1]);
    const max = Math.max(...entries.map((e) => e[1]));
    $("ranking").innerHTML = entries.map(([k, v]) => {
      const cls = k === "ours" ? "ours" : (k === state.baseline ? "sel" : "");
      const label = k === "ours" ? "Sphere mesh (ours)" : METHOD_LABEL[k];
      return `<button class="rank-row ${cls}" data-k="${k}"><span>${label}</span>` +
        `<span class="rank-bar" style="width:${(v / max) * 100}%"></span><span class="rank-val">${fmt(v, 4)}</span></button>`;
    }).join("");
    $("ranking").querySelectorAll(".rank-row:not(.ours)").forEach((r) =>
      r.addEventListener("click", () => {
        state.baseline = r.dataset.k;
        $("baseline-select").value = state.baseline;
        renderExplorer(false);
      }));

    // texture optimization slider
    $("tex-left").src = `${dir}/ours.webp`;
    $("tex-right").src = `${dir}/raycast.webp`;
    $("tex-info").textContent = fl.raycast != null
      ? `FLIP for this view: raycast only ${fmt(fl.raycast, 4)} → optimized ${fmt(fl.ours, 4)}.`
      : "";
  }

  function renderStages() {
    const m = modelOf(state.model);
    $("stages").hidden = !m.stages;
    $("stages-missing").hidden = !!m.stages;
    if (!m.stages) return;
    ["initial", "topology", "final"].forEach((n) => {
      $("st-" + n).src = `assets/stages/${m.key}/${state.budget}/${n}_${state.stageKind}.webp`;
    });
  }

  function renderExplorer(modelChanged) {
    const m = modelOf(state.model);
    if (!m) return;
    if (!m.budgets[state.budget]) state.budget = Object.keys(m.budgets)[0];
    $("model-picker").querySelectorAll("button").forEach((b) => b.classList.toggle("active", b.dataset.k === m.key));
    if (modelChanged) {
      const active = $("model-picker").querySelector("button.active");
      if (active) active.scrollIntoView({ block: "nearest", inline: "nearest", behavior: "smooth" });
    }
    segmented($("budget-seg"), Object.keys(m.budgets).map((k) => [k, `${k} spheres`]), state.budget, (v) => {
      state.budget = v; renderExplorer(false);
    });
    const b = m.budgets[state.budget];
    $("budget-info").innerHTML = `<b>${m.label}</b> · ${state.budget} spheres = <b>${b.prims}</b> renderable primitives`;
    $("tt-ours-label").textContent = `Sphere mesh (ours) · ${state.budget} spheres`;
    $("tt-base-label").textContent = `${METHOD_LABEL[state.baseline]} · ${b.prims} triangles`;
    renderTurntables();
    renderCompare();
    renderStages();
  }

  if (models.length) renderExplorer(true);
  else $("explorer").insertAdjacentHTML("beforeend", '<p class="hint">Explorer assets not built.</p>');


  // ------------------------------------------------------------------ geometry optimization viewer
  (function optimization() {
    const runs = D.optimization || [];
    const sec = $("optimization");
    if (!runs.length) { sec.hidden = true; return; }
    const SERIES = [
      ["loss", "Total", "#2b62d9"], ["sil", "Silhouette", "#d9902b"],
      ["depth", "Depth", "#2a9d6f"], ["normal", "Normal", "#a2479b"],
    ];
    const st = {
      run: runs.find((r) => r.key === "rattle_30") || runs[0],
      stage: "beam", idx: 0, timer: null,
      show: { loss: true, sil: false, depth: false, normal: false },
    };
    const base = () => `assets/optimization/${st.run.key}`;
    const pad = (n, w) => String(n).padStart(w, "0");
    const frames = () => (st.stage === "beam" ? st.run.beam : st.run.refine);

    // run picker
    if (runs.length < 2) $("opt-run-ctrl").hidden = true;
    segmented($("opt-run-seg"), runs.map((r) => [r.key, `${r.label} · ${r.spheres}`]), st.run.key, (k) => {
      st.run = runs.find((r) => r.key === k); stop(); st.idx = 0; preload(); render(true);
    });
    bindSeg($("opt-stage-seg"), "s", (v) => { stop(); st.stage = v; st.idx = 0; render(true); });
    $("opt-outline").addEventListener("change", () => {
      $("opt-outline-img").hidden = !st.run.outline || !$("opt-outline").checked;
    });

    // preload frames for smooth scrubbing
    const cache = [];
    function preload() {
      cache.length = 0;
      st.run.beam.forEach((_, i) => { const im = new Image(); im.src = `${base()}/beam/${pad(i, 2)}.webp`; cache.push(im); });
      st.run.refine.forEach((_, i) => { const im = new Image(); im.src = `${base()}/refine/${pad(i, 4)}.webp`; cache.push(im); });
    }

    // timeline
    const range = $("opt-range");
    range.addEventListener("input", () => { stop(); st.idx = Number(range.value); render(false); });
    $("opt-play").addEventListener("click", () => (st.timer ? stop() : play()));
    function play() {
      if (st.idx >= frames().length - 1) { st.idx = 0; render(false); }
      $("opt-play").textContent = "Pause";
      const dt = st.stage === "beam" ? 900 : 70;
      st.timer = setInterval(() => {
        if (st.idx >= frames().length - 1) { stop(); return; }
        st.idx++; render(false);
      }, dt);
    }
    function stop() {
      if (st.timer) clearInterval(st.timer);
      st.timer = null;
      $("opt-play").textContent = "Play";
    }

    // chart
    const svg = $("opt-chart");
    const W = 400, H = 200, P = { l: 8, r: 8, t: 12, b: 12 };
    const xOf = (i, n) => P.l + (W - P.l - P.r) * (n > 1 ? i / (n - 1) : 0);
    function seriesValues() {
      if (st.stage === "beam") return [["score", st.run.beam.map((b) => b.score), "#2b62d9"]];
      const ref = st.run.refine;
      const active = SERIES.filter(([k]) => st.show[k] && ref[0][k] != null);
      const rel = active.length > 1 || (active.length === 1 && active[0][0] !== "loss");
      return active.map(([k, , c]) => [k, ref.map((s) => (rel ? s[k] / ref[0][k] : s[k])), c]);
    }
    // keep dots round although the SVG is stretched
    const svgAspect = () => {
      const r = svg.getBoundingClientRect();
      return r.width && r.height ? (r.width / W) / (r.height / H) : 1;
    };
    function drawChart() {
      const series = seriesValues();
      const n = frames().length;
      const all = series.flatMap((s) => s[1]);
      if (!all.length) { svg.innerHTML = ""; return; }
      let lo = Math.min(...all), hi = Math.max(...all);
      if (hi - lo < 1e-12) { hi += 1e-6; lo -= 1e-6; }
      const yOf = (v) => P.t + (H - P.t - P.b) * (1 - (v - lo) / (hi - lo));
      let html = "";
      for (let g = 0; g <= 4; g++) {
        const y = P.t + (H - P.t - P.b) * g / 4;
        html += `<line class="grid" x1="0" x2="${W}" y1="${y}" y2="${y}"/>`;
      }
      series.forEach(([, vals, color]) => {
        const pts = vals.map((v, i) => `${xOf(i, n).toFixed(1)},${yOf(v).toFixed(1)}`);
        html += `<polyline class="line ghost" stroke="${color}" points="${pts.join(" ")}"/>`;
        html += `<polyline class="line" stroke="${color}" points="${pts.slice(0, st.idx + 1).join(" ")}"/>`;
      });
      const cx = xOf(st.idx, n);
      html += `<line class="cursor" x1="${cx}" x2="${cx}" y1="0" y2="${H}"/>`;
      const asp = svgAspect();
      series.forEach(([, vals, color]) => {
        html += `<ellipse cx="${cx}" cy="${yOf(vals[st.idx])}" rx="${4.5 / asp}" ry="4.5" fill="${color}"/>`;
      });
      svg.innerHTML = html;
    }
    let scrubbing = false;
    const scrub = (e) => {
      const r = svg.getBoundingClientRect();
      const x = ((e.clientX - r.left) / r.width) * W;
      const n = frames().length;
      st.idx = Math.max(0, Math.min(n - 1, Math.round(((x - P.l) / (W - P.l - P.r)) * (n - 1))));
      render(false);
    };
    svg.addEventListener("pointerdown", (e) => { stop(); scrubbing = true; svg.setPointerCapture(e.pointerId); scrub(e); });
    svg.addEventListener("pointermove", (e) => { if (scrubbing) scrub(e); });
    svg.addEventListener("pointerup", () => { scrubbing = false; });

    function legend() {
      if (st.stage === "beam") {
        $("opt-legend").innerHTML = '<span class="note">One point per accepted state of the beam search. Spheres are added or removed until the target count is reached. Click or drag in the chart to jump.</span>';
        return;
      }
      const ref = st.run.refine;
      $("opt-legend").innerHTML = SERIES.filter(([k]) => ref[0][k] != null).map(([k, label, c]) =>
        `<label><input type="checkbox" data-k="${k}" ${st.show[k] ? "checked" : ""}><span class="sw" style="background:${c}"></span>${label}</label>`).join("") +
        '<span class="note">Select loss terms to plot. With several terms, each curve is shown relative to its value at step 0. Click or drag in the chart to jump.</span>';
      $("opt-legend").querySelectorAll("input").forEach((cb) => cb.addEventListener("change", () => {
        st.show[cb.dataset.k] = cb.checked;
        if (!Object.values(st.show).some(Boolean)) { st.show.loss = true; legend(); }
        drawChart();
      }));
    }

    // turntables of the three stages
    const tv = { mat: $("opt-tv-mat"), top: $("opt-tv-top"), final: $("opt-tv-final") };
    const vids = Object.values(tv);
    setInterval(() => {
      if (st.stage !== "turn" || vids[0].paused) return;
      vids.slice(1).forEach((v) => {
        if (v.readyState >= 2 && Math.abs(v.currentTime - vids[0].currentTime) > 0.08) v.currentTime = vids[0].currentTime;
      });
    }, 400);
    function renderTurntables() {
      const r = st.run;
      const desc = (s) => (s ? ` · ${s.spheres} spheres, ${s.edges} cones, ${s.triangles} prisms` : "");
      $("opt-tl-mat").textContent = "Structural-MAT" + desc(r.stages.mat);
      $("opt-tl-top").textContent = "+ Topology search" + desc(r.stages.top);
      $("opt-tl-final").textContent = "+ Refinement (ours)" + desc(r.stages.final);
      let pending = vids.length;
      const go = () => { if (--pending === 0) vids.forEach((x) => { x.currentTime = 0; x.play().catch(() => {}); }); };
      Object.entries(tv).forEach(([k, v]) => {
        const src = `${base()}/turntable_${k}.mp4`;
        if (v.getAttribute("src") === src && v.readyState >= 2) { go(); return; }
        v.addEventListener("loadeddata", go, { once: true });
        v.setAttribute("src", src);
      });
    }

    function render(full) {
      const turn = st.stage === "turn";
      $("opt-steps").hidden = turn;
      $("opt-turn").hidden = !turn;
      if (!turn) vids.forEach((v) => v.pause());
      if (turn) { if (full) renderTurntables(); return; }

      const r = st.run, n = frames().length;
      if (full) {
        $("opt-ref").src = `${base()}/reference.webp`;
        if (r.outline) $("opt-outline-img").src = `${base()}/outline.png`;
        $("opt-outline-img").hidden = !r.outline || !$("opt-outline").checked;
        range.max = n - 1;
        $("opt-beam-extra").hidden = st.stage !== "beam";
        $("opt-chart-title").textContent = st.stage === "beam"
          ? "Rendering loss along the accepted beam path"
          : "Loss during refinement";
        legend();
      }
      range.value = st.idx;
      if (st.stage === "beam") {
        const b = r.beam[st.idx];
        $("opt-sm").src = `${base()}/beam/${pad(st.idx, 2)}.webp`;
        $("opt-sm-label").textContent = st.idx === 0 ? "Sphere mesh · initial cut" : `Sphere mesh · beam state ${st.idx}`;
        $("opt-k1-label").textContent = "Spheres";
        $("opt-k1").innerHTML = `${b.count} <small>/ ${r.spheres}</small>`;
        $("opt-k2").textContent = b.score.toFixed(4);
        $("opt-pos").textContent = `State ${st.idx} of ${n - 1}`;
        const layer = st.idx > 0 ? r.layers[st.idx - 1] : null;
        $("opt-cand-hint").hidden = !layer;
        if (layer) {
          $("opt-layer-title").textContent = `Beam candidates kept with ${layer.count} spheres`;
          $("opt-cands").innerHTML = layer.kept.map((c, k) =>
            `<div class="opt-cand ${c.on_path ? "on" : ""}"><img src="${base()}/layers/${pad(st.idx - 1, 2)}_${pad(k, 2)}.webp" alt=""><div>${c.score.toFixed(4)}</div></div>`).join("");
        } else {
          $("opt-layer-title").textContent = "Beam candidates";
          $("opt-cands").innerHTML = '<p class="hint" style="grid-column:1/-1">This is the initial Structural-MAT cut. Press Play or drag the slider to step through the beam search.</p>';
        }
      } else {
        const s = r.refine[st.idx];
        $("opt-sm").src = `${base()}/refine/${pad(st.idx, 4)}.webp`;
        $("opt-sm-label").textContent = "Sphere mesh · topology fixed";
        $("opt-k1-label").textContent = "Step";
        $("opt-k1").textContent = `${s.step}`;
        $("opt-k2").textContent = s.loss.toFixed(4);
        $("opt-pos").textContent = `Step ${s.step} of ${r.refine[n - 1].step}`;
      }
      drawChart();
    }

    preload();
    render(true);
    window.addEventListener("resize", drawChart);
  })();


  // ------------------------------------------------------------------ texture optimization viewer
  (function textureViewer() {
    const runs = D.texture || [];
    if (!runs.length) { $("texopt").hidden = true; return; }
    const ATLAS_LABEL = { cones: "Cones", spheres: "Spheres", faces: "Triangles" };
    const st = {
      run: runs.find((r) => r.key === "rattle_30") || runs[0],
      variant: "ours", show: "img", metric: "flip", atlas: "cones", it: 1, timer: null,
    };
    const base = () => `assets/texture/${st.run.key}`;
    const pad3 = (n) => String(n).padStart(3, "0");
    const N = () => st.run.iterations;

    if (runs.length < 2) $("tex-run-ctrl").hidden = true;
    segmented($("tex-run-seg"), runs.map((r) => [r.key, `${r.label} · ${r.spheres}`]), st.run.key, (k) => {
      stop(); st.run = runs.find((r) => r.key === k); st.it = 1; preload(); render(true);
    });
    bindSeg($("tex-show-seg"), "v", (v) => { st.show = v; render(false); });
    bindSeg($("tex-metric-seg"), "m", (m) => { st.metric = m; render(false); });

    const cache = [];
    function preload() {
      cache.length = 0;
      for (let i = 1; i <= N(); i++) {
        [`${base()}/${st.variant}/${pad3(i)}.webp`, `${base()}/${st.variant}/${pad3(i)}_flip.webp`].forEach((src) => {
          const im = new Image(); im.src = src; cache.push(im);
        });
      }
    }

    // timeline
    const range = $("tex-range");
    range.addEventListener("input", () => { stop(); st.it = Number(range.value); render(false); });
    $("tex-play").addEventListener("click", () => (st.timer ? stop() : play()));
    function play() {
      if (st.it >= N()) { st.it = 1; render(false); }
      $("tex-play").textContent = "Pause";
      st.timer = setInterval(() => {
        if (st.it >= N()) { stop(); return; }
        st.it++; render(false);
      }, 160);
    }
    function stop() {
      if (st.timer) clearInterval(st.timer);
      st.timer = null;
      $("tex-play").textContent = "Play";
    }

    // chart: both variants, selected one solid
    const svg = $("tex-chart");
    const W = 400, H = 200, P = { l: 8, r: 8, t: 12, b: 12 };
    const xOf = (i) => P.l + (W - P.l - P.r) * ((i - 1) / Math.max(N() - 1, 1));
    const svgAspect = () => {
      const r = svg.getBoundingClientRect();
      return r.width && r.height ? (r.width / W) / (r.height / H) : 1;
    };
    function drawChart() {
      const M = st.run.metrics;
      const all = M[st.variant][st.metric];
      let lo = Math.min(...all), hi = Math.max(...all);
      if (hi - lo < 1e-9) { hi += 1e-6; lo -= 1e-6; }
      const yOf = (v) => P.t + (H - P.t - P.b) * (1 - (v - lo) / (hi - lo));
      let html = "";
      for (let g = 0; g <= 4; g++) {
        const y = P.t + (H - P.t - P.b) * g / 4;
        html += `<line class="grid" x1="0" x2="${W}" y1="${y}" y2="${y}"/>`;
      }
      const vals = M[st.variant][st.metric];
      const pts = vals.map((x, i) => `${xOf(i + 1).toFixed(1)},${yOf(x).toFixed(1)}`);
      html += `<polyline class="line ghost" stroke="#2b62d9" points="${pts.join(" ")}"/>`;
      html += `<polyline class="line" stroke="#2b62d9" points="${pts.slice(0, st.it).join(" ")}"/>`;
      const cx = xOf(st.it);
      html += `<line class="cursor" x1="${cx}" x2="${cx}" y1="0" y2="${H}"/>`;
      const v = M[st.variant][st.metric][st.it - 1];
      const asp = svgAspect();
      html += `<ellipse cx="${cx}" cy="${yOf(v)}" rx="${4.5 / asp}" ry="4.5" fill="#2b62d9"/>`;
      svg.innerHTML = html;
    }
    let scrubbing = false;
    const scrub = (e) => {
      const r = svg.getBoundingClientRect();
      const x = ((e.clientX - r.left) / r.width) * W;
      st.it = Math.max(1, Math.min(N(), 1 + Math.round(((x - P.l) / (W - P.l - P.r)) * (N() - 1))));
      render(false);
    };
    svg.addEventListener("pointerdown", (e) => { stop(); scrubbing = true; svg.setPointerCapture(e.pointerId); scrub(e); });
    svg.addEventListener("pointermove", (e) => { if (scrubbing) scrub(e); });
    svg.addEventListener("pointerup", () => { scrubbing = false; });

    // synchronized magnifier on both images
    const ZOOM = 3;
    const hosts = [...document.querySelectorAll("#texopt .lens-host")];
    function moveLens(fx, fy) {
      hosts.forEach((h) => {
        const lens = h.querySelector(".lens");
        const img = h.querySelector("img");
        const w = h.clientWidth, hh = h.clientHeight;
        lens.hidden = false;
        lens.style.left = `${fx * w}px`;
        lens.style.top = `${fy * hh}px`;
        lens.style.backgroundImage = `url("${img.src}")`;
        lens.style.backgroundSize = `${w * ZOOM}px ${hh * ZOOM}px`;
        lens.style.backgroundPosition = `${-(fx * w * ZOOM - 85)}px ${-(fy * hh * ZOOM - 85)}px`;
      });
    }
    let lensPos = null;
    hosts.forEach((h) => {
      h.addEventListener("pointermove", (e) => {
        const r = h.getBoundingClientRect();
        lensPos = [(e.clientX - r.left) / r.width, (e.clientY - r.top) / r.height];
        moveLens(...lensPos);
      });
      h.addEventListener("pointerleave", () => { lensPos = null; hosts.forEach((x) => (x.querySelector(".lens").hidden = true)); });
    });

    function render(full) {
      const r = st.run;
      if (full) {
        range.max = N();
        const atl = r.atlases;
        if (!atl.includes(st.atlas)) st.atlas = atl[0];
        segmented($("tex-atlas-seg"), atl.map((a) => [a, ATLAS_LABEL[a] || a]), st.atlas, (a) => { st.atlas = a; render(false); });
        $("tex-atlas").parentElement.hidden = !atl.length;
      }
      range.value = st.it;
      const sfx = st.show === "flip" ? "_flip" : "";
      $("tex-ref").src = `${base()}/reference.webp`;
      $("tex-it").src = `${base()}/${st.variant}/${pad3(st.it)}${sfx}.webp`;
      $("tex-it-label").textContent = "Textured sphere mesh" +
        (st.show === "flip" ? " · FLIP error" : "");
      const M = r.metrics[st.variant];
      $("tex-k-it").innerHTML = `${st.it} <small>/ ${N()}</small>`;
      $("tex-k-flip").textContent = M.flip[st.it - 1].toFixed(4);
      $("tex-k-psnr").textContent = M.psnr[st.it - 1].toFixed(2);
      $("tex-chart-title").textContent = st.metric === "flip" ? "FLIP for this view ↓" : "PSNR for this view (dB) ↑";
      $("tex-pos").textContent = `Iteration ${st.it} of ${N()}`;
      if (st.atlas) $("tex-atlas").src = `${base()}/${st.variant}/${st.atlas}/${pad3(st.it)}.webp`;
      drawChart();
      if (lensPos) moveLens(...lensPos);
    }

    preload();
    render(true);
    window.addEventListener("resize", drawChart);
  })();

  // ------------------------------------------------------------------ results table
  (function results() {
    const S = (D.numbers && D.numbers.summary) || {};
    if (!Object.keys(S).length) return;
    const st = { metric: "flip" };
    segmented($("metric-seg"), ["flip", "lpips", "psnr", "ssim"].map((k) => [k, METRIC_LABEL[k]]), st.metric, (v) => { st.metric = v; draw(); });

    function draw() {
      const T = S[st.metric] || {};
      const methods = Object.keys(T);
      const budgets = [...new Set(methods.flatMap((m) => Object.keys(T[m])))].sort((a, b) => a - b);
      const lower = LOWER_BETTER[st.metric];
      const best = {};
      budgets.forEach((bu) => {
        const vals = methods.map((m) => T[m][bu]).filter((v) => v != null);
        best[bu] = lower ? Math.min(...vals) : Math.max(...vals);
      });
      const order = ["Sphere Mesh"].concat(D.methods.map((m) => m.key)).filter((m) => T[m]);
      const dec = st.metric === "psnr" ? 2 : 4;
      $("results-table").innerHTML =
        `<thead><tr><th>Method</th>${budgets.map((b) => `<th>${b} spheres</th>`).join("")}</tr></thead><tbody>` +
        order.map((m) => `<tr class="${m === "Sphere Mesh" ? "ours" : ""}"><td>${METHOD_LABEL[m] || m}</td>` +
          budgets.map((bu) => {
            const v = T[m][bu];
            return `<td class="${v === best[bu] ? "best" : ""}">${fmt(v, dec)}</td>`;
          }).join("") + "</tr>").join("") + "</tbody>";
    }
    draw();
  })();

  // ------------------------------------------------------------------ plot tabs
  (function plots() {
    const tabs = [
      ["Image metrics", ["image_metrics"],
        "PSNR, SSIM, FLIP and LPIPS of all methods for each sphere budget (every method gets the same primitive budget)."],
      ["Geometric distance", ["geometric_distance"],
        "Chamfer and Hausdorff distances to the input mesh, computed on 128k surface samples."],
      ["Render-channel distance", ["render_channels"],
        "Silhouette, depth and normal losses between each LOD model and the input mesh, rendered from 128 views."],
      ["Texturing variants", ["texturing_variants"],
        "Raycasting initialization only, texture optimization only, and raycasting initialization + optimization (ours)."],
      ["Geometry optimization", ["geo_opt_render", "geo_opt_geometry"],
        "Effect of our geometry optimization relative to the Structural-MAT input (MAT = 100%): after topology search (TOP) and after refinement (FINAL). " +
        "Top: render-channel metrics. Bottom: geometric distances."],
    ].filter(([, figs]) => figs.every((f) => D.figures[f]));
    if (!tabs.length) return;
    const el = $("plot-tabs");
    el.innerHTML = tabs.map(([label], i) => `<button data-i="${i}" class="${i ? "" : "active"}">${label}</button>`).join("");
    const show = (i) => {
      const [, figs, caption] = tabs[i];
      $("plot-imgs").innerHTML = figs.map((f) =>
        `<img src="${D.figures[f].src}" width="${D.figures[f].w}" height="${D.figures[f].h}" alt="">`).join("");
      $("plot-caption").textContent = caption;
      el.querySelectorAll("button").forEach((b) => b.classList.toggle("active", b.dataset.i === String(i)));
    };
    el.querySelectorAll("button").forEach((b) => b.addEventListener("click", () => show(Number(b.dataset.i))));
    show(0);
  })();

  // ------------------------------------------------------------------ performance tables
  (function perf() {
    const N = D.numbers || {};
    if (N.speed) {
      $("speed-table").innerHTML =
        "<thead><tr><th>Spheres</th><th>Triangles</th><th>Ours ms</th><th>RoLoPM ms</th><th>Speed-up</th><th>FLIP ours</th><th>FLIP RoLoPM</th></tr></thead><tbody>" +
        N.speed.map((s) => `<tr><td>${s.spheres}</td><td>${s.baseline_prims}</td><td>${fmt(s.sm_ms, 2)}</td><td>${fmt(s.baseline_ms, 2)}</td>` +
          `<td class="best">${fmt(s.speedup, 2)}×</td><td>${fmt(s.sm_flip, 4)}</td><td>${fmt(s.baseline_flip, 4)}</td></tr>`).join("") + "</tbody>";
    }
  })();

  // ------------------------------------------------------------------ bibtex copy
  $("copy-bib").addEventListener("click", () => {
    const txt = $("bib-text").textContent;
    (navigator.clipboard ? navigator.clipboard.writeText(txt) : Promise.reject()).then(
      () => { $("copy-bib").textContent = "Copied"; setTimeout(() => ($("copy-bib").textContent = "Copy"), 1500); },
      () => {});
  });
})();
